INSERT INTO risks (risk_id, project_code, risk_title, description, category, probability, impact, risk_level, risk_owner, due_date, status, mitigation_plan, closure_notes, source) VALUES
  (1001, 'PRJ-01', 'احتمال تأخر جدول ترقية نظام تخطيط موارد المؤسسة', 'احتمال تأخر جدول ترقية نظام تخطيط موارد المؤسسة (ERP) عن الموعد المخطط، مما يؤخر بدء اختبارات التكامل مع المنصة.', 'تقني / تكاملي', 'متوسطة (3)', 'مرتفع (4)', 'متوسط', 'م. فيصل القحطاني', NULL, 'نشط', 'التنسيق المسبق مع إدارة الأنظمة المركزية لتثبيت نافذة الترقية، ووضع خطة تكامل بديلة مرحلية.', NULL, 'Manual'),
  (1002, 'PRJ-01', 'نقص توفر خبراء الشؤون المالية', 'نقص توفر خبراء الشؤون المالية (SMEs) خلال فترة إغلاق الميزانية السنوية، مما يؤثر على مراجعة سيناريوهات الاختبار.', 'موارد بشرية', 'مرتفعة (4)', 'متوسط (3)', 'متوسط', 'أ. عبدالعزيز الدوسري', NULL, 'نشط', 'الاتفاق المسبق مع إدارة المالية على جدول تفرغ جزئي للخبراء خارج فترة الإغلاق المحاسبي.', NULL, 'Manual'),
  (1003, 'PRJ-01', 'مقاومة بعض كبار المعتمدين للتخلي عن مسار الاعتماد الورقي المعتاد لصالح الاعتماد', 'مقاومة بعض كبار المعتمدين للتخلي عن مسار الاعتماد الورقي المعتاد لصالح الاعتماد الإلكتروني.', 'تغيير مؤسسي', 'مرتفعة (4)', 'متوسط (3)', 'متوسط', 'أ. نورة العتيبي', NULL, 'نشط', 'برنامج توعية وتدريب مكثف لكبار المعتمدين، ودعم مباشر من راعي المشروع لتعزيز الالتزام.', NULL, 'Manual'),
  (1004, 'PRJ-01', 'احتمال اكتشاف سجلات تاريخية غير مُصنفة', 'احتمال اكتشاف سجلات تاريخية غير مُصنفة (Unmapped Records) أثناء ترحيل بيانات المطالبات من النظام القديم.', 'بيانات وترحيل', 'مرتفعة (4)', 'متوسط (3)', 'متوسط', 'م. سلطان الحربي', NULL, 'نشط', 'تنفيذ جولة تحقق مبدئي من جودة البيانات قبل الترحيل الفعلي، وتخصيص فريق لمعالجة الاستثناءات يدوياً.', NULL, 'Manual'),
  (1005, 'PRJ-01', 'تأخر تسليم بيئة الاختبار من مزود المنصة السحابية عن الموعد التعاقدي.', 'تأخر تسليم بيئة الاختبار من مزود المنصة السحابية عن الموعد التعاقدي.', 'مورد خارجي', 'منخفضة (2)', 'متوسط (3)', 'منخفض', 'م. فيصل القحطاني', NULL, 'نشط', 'إدراج غرامات تأخير تعاقدية، ومتابعة أسبوعية مع مدير حساب المورد.', NULL, 'Manual'),
  (1006, 'PRJ-01', 'احتمال تجاوز الميزانية المخصصة لبند خدمات التكامل بسبب تعقيدات غير متوقعة في واجهات الربط.', 'احتمال تجاوز الميزانية المخصصة لبند خدمات التكامل بسبب تعقيدات غير متوقعة في واجهات الربط.', 'مالي', 'منخفضة (2)', 'مرتفع (4)', 'متوسط', 'أ. عبدالعزيز الدوسري', NULL, 'نشط', 'احتفاظ باحتياطي طوارئ بنسبة 5% ضمن بند التكامل، ومراجعة شهرية للانحراف المالي.', NULL, 'Manual'),
  (1007, 'PRJ-01', 'ثغرات أمنية محتملة في واجهة برمجة التطبيقات', 'ثغرات أمنية محتملة في واجهة برمجة التطبيقات (API) الخاصة بالتكامل مع نظام ERP.', 'أمن معلومات', 'منخفضة (2)', 'مرتفع (4)', 'متوسط', 'إدارة أمن المعلومات', NULL, 'نشط', 'إجراء اختبار اختراق (Penetration Test) قبل الإطلاق للإنتاج، وتطبيق ضوابط التشفير المعتمدة.', NULL, 'Manual'),
  (1008, 'PRJ-01', 'دوران الموظفين الرئيسيين في فريق المشروع لدى الجهات المشاركة قد يؤثر على استمرار', 'دوران الموظفين الرئيسيين في فريق المشروع لدى الجهات المشاركة قد يؤثر على استمرارية المعرفة.', 'موارد بشرية', 'متوسطة (3)', 'متوسط (3)', 'متوسط', 'أ. نورة العتيبي', NULL, 'نشط', 'توثيق شامل لإجراءات العمل، وتحديد بديل مدرب لكل دور رئيسي في الفريق.', NULL, 'Manual'),
  (1009, 'PRJ-01', 'احتمال تأخر اعتماد التعديلات التنظيمية اللازمة على دليل الصلاحيات المالية ليتواف', 'احتمال تأخر اعتماد التعديلات التنظيمية اللازمة على دليل الصلاحيات المالية ليتوافق مع مسارات الاعتماد الإلكتروني.', 'تنظيمي / امتثال', 'منخفضة (2)', 'مرتفع (4)', 'متوسط', 'أ. ريم الشهري', NULL, 'نشط', 'رفع مسودة التعديلات المطلوبة للجنة التوجيهية مبكراً، والتنسيق مع إدارة الشؤون القانونية.', NULL, 'Manual'),
  (1010, 'PRJ-01', 'ضعف جودة الاتصال بالإنترنت لدى بعض الجهات المشاركة في المناطق النائية قد يؤثر عل', 'ضعف جودة الاتصال بالإنترنت لدى بعض الجهات المشاركة في المناطق النائية قد يؤثر على تجربة الاستخدام.', 'تقني / بنية تحتية', 'منخفضة (2)', 'منخفض (2)', 'منخفض', 'م. سلطان الحربي', NULL, 'نشط', 'توفير نسخة مخففة من واجهة المستخدم تعمل بكفاءة على اتصال منخفض السرعة.', NULL, 'Manual'),
  (2001, 'PRJ-02', 'تأخر جاهزية التكامل لدى جهتين من الجهات المشاركة', 'تأخر جاهزية التكامل لدى جهتين من الجهات المشاركة (وزارة العدل وGOSI) عن النافذة الزمنية المتفقة', 'فني / جدولة', 'مرتفعة', 'مرتفع', 'عالٍ', 'عبدالله القحطاني', NULL, 'نشط', 'اعتماد نهج تكامل متوازٍ وإطلاق مرحلي؛ متابعة أسبوعية على مستوى القيادة', NULL, 'Manual'),
  (2002, 'PRJ-02', 'محدودية سعة منصة النفاذ الوطني الموحد', 'محدودية سعة منصة النفاذ الوطني الموحد (SSO) خلال ذروة حركة المستخدمين عند الإطلاق', 'فني', 'متوسطة', 'مرتفع', 'عالٍ', 'خالد الدوسري', NULL, 'نشط', 'اختبارات حمل مشتركة مع المركز الوطني للمعلومات وحجز سعة إضافية قبل الإطلاق', NULL, 'Manual'),
  (2003, 'PRJ-02', 'عدم اكتمال مراجعة المحتوى العربي', 'عدم اكتمال مراجعة المحتوى العربي (المصطلحات والنصوص الإجرائية) قبل الإطلاق', 'محتوى / جودة', 'متوسطة', 'متوسط', 'متوسط', 'سارة الغامدي', NULL, 'نشط', 'تخصيص مراجعين إضافيين وجدولة مراجعات أسبوعية مع الجهات المعنية', NULL, 'Manual'),
  (2004, 'PRJ-02', 'فجوات في مطابقة معايير إمكانية الوصول', 'فجوات في مطابقة معايير إمكانية الوصول (WCAG 2.1 AA) رصدها التدقيق الأخير', 'امتثال', 'متوسطة', 'مرتفع', 'عالٍ', 'ريم الشهري', NULL, 'نشط', 'بناء قائمة معالجة (Remediation Backlog) وإعادة اختبار قبل كل بوابة مراجعة', NULL, 'Manual'),
  (2005, 'PRJ-02', 'تأخر اعتماد شهادة الامتثال لبوابة الدفع الإلكتروني الخارجية اللازمة لخدمات السداد', 'تأخر اعتماد شهادة الامتثال لبوابة الدفع الإلكتروني الخارجية اللازمة لخدمات السداد', 'مورد خارجي', 'متوسطة', 'مرتفع', 'عالٍ', 'فيصل العتيبي', NULL, 'مراقَب', 'التنسيق المبكر مع مزود الدفع المرخص من ساما، وتجهيز مزود بديل احتياطي', NULL, 'Manual'),
  (2006, 'PRJ-02', 'تدني جودة بيانات الأنظمة القديمة لدى بعض الجهات يحول دون التعبئة المسبقة الدقيقة للنماذج', 'تدني جودة بيانات الأنظمة القديمة لدى بعض الجهات يحول دون التعبئة المسبقة الدقيقة للنماذج', 'بيانات', 'مرتفعة', 'متوسط', 'متوسط', 'عبدالله القحطاني', NULL, 'نشط', 'تنفيذ دورة تنقية بيانات وتوفير آلية إدخال يدوي احتياطية للمستفيد', NULL, 'Manual'),
  (2007, 'PRJ-02', 'احتمال فقدان موارد رئيسية من فريق شريك التنفيذ خلال مرحلة التكامل الحرجة', 'احتمال فقدان موارد رئيسية من فريق شريك التنفيذ خلال مرحلة التكامل الحرجة', 'موارد بشرية', 'منخفضة', 'مرتفع', 'متوسط', 'تركي العنزي', NULL, 'مراقَب', 'خطة نقل معرفة موثقة وتوفير موارد احتياطية مدربة', NULL, 'Manual'),
  (2008, 'PRJ-02', 'توسّع نطاق المشروع نتيجة طلبات إضافة خدمات جديدة من جهات مشاركة', 'توسّع نطاق المشروع نتيجة طلبات إضافة خدمات جديدة من جهات مشاركة', 'نطاق', 'متوسطة', 'متوسط', 'متوسط', 'فيصل العتيبي', NULL, 'مراقَب', 'تفعيل لجنة التحكم بالتغيير وربط أي إضافة بميزانية وجدول منفصلين', NULL, 'Manual'),
  (2009, 'PRJ-02', 'ثغرات أمنية محتملة في بوابة واجهات البرمجة', 'ثغرات أمنية محتملة في بوابة واجهات البرمجة (API Gateway) الموحدة', 'أمن معلومات', 'منخفضة', 'مرتفع', 'متوسط', 'خالد الدوسري', NULL, 'نشط', 'اختبار اختراق دوري ومراجعة الامتثال لضوابط الهيئة الوطنية للأمن السيبراني', NULL, 'Manual'),
  (2010, 'PRJ-02', 'تأخر قرارات اللجنة التوجيهية بسبب ازدحام جدول الاجتماعات التنفيذية', 'تأخر قرارات اللجنة التوجيهية بسبب ازدحام جدول الاجتماعات التنفيذية', 'حوكمة', 'متوسطة', 'متوسط', 'متوسط', 'نورة الحربي', NULL, 'مراقَب', 'إرسال حزم قرار مسبقة (Pre-read) وتفويض صلاحيات محددة لمدير المشروع', NULL, 'Manual'),
  (2011, 'PRJ-02', 'تجاوز ميزانية بند التكامل نتيجة تمديد الدعم الفني للجهتين المتأخرتين', 'تجاوز ميزانية بند التكامل نتيجة تمديد الدعم الفني للجهتين المتأخرتين', 'مالي', 'مرتفعة', 'متوسط', 'متوسط', 'فيصل العتيبي', NULL, 'نشط', 'تقديم طلب تغيير لإعادة تخصيص الاحتياطي إلى بند التكامل', NULL, 'Manual'),
  (3001, 'PRJ-03', 'استمرار مراجعة اللجنة الوطنية لتصنيف البيانات قد يفرض تغييرات إضافية على متطلبات', 'استمرار مراجعة اللجنة الوطنية لتصنيف البيانات قد يفرض تغييرات إضافية على متطلبات التصنيف تتطلب إعادة بناء قواعد الاستيعاب مجدداً.', 'تنظيمي', 'مرتفعة', 'مرتفع', 'عالٍ', 'ريم المطيري', NULL, 'نشط', 'التنسيق المباشر مع اللجنة لتثبيت المتطلبات النهائية كتابياً؛ تصميم قواعد التصنيف بشكل معياري (Modular) لتقليل أثر أي تغيير مستقبلي.', NULL, 'Manual'),
  (3002, 'PRJ-03', 'عجز بعض الجهات المشمولة عن توفير صلاحيات الوصول لأنظمة المصدر لديها خلال النافذة', 'عجز بعض الجهات المشمولة عن توفير صلاحيات الوصول لأنظمة المصدر لديها خلال النافذة الزمنية المتفق عليها.', 'اعتمادية خارجية', 'مرتفعة', 'مرتفع', 'عالٍ', 'نورة العتيبي', NULL, 'نشط', 'تصعيد رسمي عبر اللجنة التوجيهية لكل جهة متأخرة؛ إدراج بند التزام زمني في مذكرات التفاهم المستقبلية مع الجهات.', NULL, 'Manual'),
  (3003, 'PRJ-03', 'تدهور أداء استعلامات المستودع التحليلي مع تزايد أحجام البيانات التاريخية المجمّع', 'تدهور أداء استعلامات المستودع التحليلي مع تزايد أحجام البيانات التاريخية المجمّعة من الجهات.', 'تقني', 'متوسطة', 'مرتفع', 'عالٍ', 'عبدالرحمن الحربي', NULL, 'نشط', 'تطبيق تقسيم الجداول (Partitioning) والفهرسة المسبقة؛ اختبارات حمل دورية عند كل زيادة جوهرية في حجم البيانات.', NULL, 'Manual'),
  (3004, 'PRJ-03', 'فقدان موارد متخصصة في هندسة البيانات لصالح برامج أخرى منافسة لدى الشريك التنفيذي.', 'فقدان موارد متخصصة في هندسة البيانات لصالح برامج أخرى منافسة لدى الشريك التنفيذي.', 'موارد بشرية', 'متوسطة', 'مرتفع', 'عالٍ', 'فيصل الدوسري', NULL, 'نشط', 'تثبيت بند حصرية الموارد الأساسية ضمن اتفاقية مستوى الخدمة مع الشريك؛ خطة إحلال واحتفاظ بالمعرفة (Knowledge Transfer).', NULL, 'Manual'),
  (3005, 'PRJ-03', 'تباين تعريفات المؤشرات بين الجهات المشمولة يحول دون إمكانية التجميع أو المقارنة', 'تباين تعريفات المؤشرات بين الجهات المشمولة يحول دون إمكانية التجميع أو المقارنة الموثوقة على مستوى المنصة.', 'جودة بيانات', 'مرتفعة', 'متوسط', 'عالٍ', 'ريم المطيري', NULL, 'نشط', 'ورش عمل توحيد تعريفات المؤشرات مع الجهات قبل بدء أي دفعة استيعاب جديدة؛ قاموس بيانات مركزي معتمد.', NULL, 'Manual'),
  (3006, 'PRJ-03', 'استنفاد الميزانية المعتمدة قبل اكتمال المشروع نتيجة تمديد الجدول الزمني وتكاليف', 'استنفاد الميزانية المعتمدة قبل اكتمال المشروع نتيجة تمديد الجدول الزمني وتكاليف التعاقد الإضافية مع الشريك.', 'مالي', 'مرتفعة', 'مرتفع', 'عالٍ', 'خالد الشهري', NULL, 'نشط', 'تقديم طلب تمويل تكميلي مبكراً؛ مراجعة شهرية لمعدل الصرف مقابل النطاق المتبقي وتحديث توقعات التكلفة عند الإكمال (EAC).', NULL, 'Manual'),
  (3007, 'PRJ-03', 'تأخر تسليم بيئات الاختبار من مزود الحوسبة السحابية يؤثر على جدولة اختبار قبول المستخدم.', 'تأخر تسليم بيئات الاختبار من مزود الحوسبة السحابية يؤثر على جدولة اختبار قبول المستخدم.', 'تقني', 'منخفضة', 'متوسط', 'منخفض', 'عبدالرحمن الحربي', NULL, 'نشط', 'حجز مسبق لبيئات الاختبار قبل ثمانية أسابيع من الموعد المطلوب؛ اتفاقية مستوى خدمة واضحة مع المزود.', NULL, 'Manual'),
  (3008, 'PRJ-03', 'ضعف جودة البيانات الواردة من بعض أنظمة المصدر لدى الجهات', 'ضعف جودة البيانات الواردة من بعض أنظمة المصدر لدى الجهات (قيم مفقودة أو غير متسقة) يستهلك وقتاً إضافياً في التنقية.', 'جودة بيانات', 'متوسطة', 'متوسط', 'متوسط', 'ريم المطيري', NULL, 'نشط', 'تطبيق قواعد تحقق آلية عند نقطة الاستيعاب؛ تقارير جودة بيانات أسبوعية تُرسل للجهات المصدر لمعالجة الاستثناءات.', NULL, 'Manual'),
  (3009, 'PRJ-03', 'احتمال تسرب أو الوصول غير المصرح به لبيانات حساسة أثناء مرحلة الاستيعاب قبل اكتم', 'احتمال تسرب أو الوصول غير المصرح به لبيانات حساسة أثناء مرحلة الاستيعاب قبل اكتمال تطبيق ضوابط التصنيف الجديدة.', 'أمن معلومات', 'منخفضة', 'مرتفع', 'متوسط', 'عبدالرحمن الحربي', NULL, 'نشط', 'تشفير البيانات أثناء النقل والتخزين؛ صلاحيات وصول مقيدة على أساس الحاجة للمعرفة إلى حين استقرار ضوابط التصنيف.', NULL, 'Manual'),
  (3010, 'PRJ-03', 'تجاوز الجدول الزمني المُمدد لموعد نهاية السنة المالية الحالية يعقّد إجراءات اعتم', 'تجاوز الجدول الزمني المُمدد لموعد نهاية السنة المالية الحالية يعقّد إجراءات اعتماد التمويل التكميلي.', 'مالي', 'متوسطة', 'متوسط', 'متوسط', 'خالد الشهري', NULL, 'نشط', 'التنسيق المبكر مع الجهات المالية المختصة لتقديم طلب التمويل التكميلي قبل إغلاق السنة المالية بفترة كافية.', NULL, 'Manual'),
  (3011, 'PRJ-03', 'انخفاض ثقة الجهات المشمولة في التزام المشروع بالمواعيد يؤدي إلى تراجع أولوية دعم', 'انخفاض ثقة الجهات المشمولة في التزام المشروع بالمواعيد يؤدي إلى تراجع أولوية دعمها الفني للمشروع.', 'أصحاب مصلحة', 'متوسطة', 'متوسط', 'متوسط', 'نورة العتيبي', NULL, 'نشط', 'تواصل دوري شفاف مع نقاط الاتصال في الجهات؛ مشاركة خطة التعافي المعتمدة والمعالم المحدثة معهم مباشرة.', NULL, 'Manual'),
  (3012, 'PRJ-03', 'عدم كفاية تغطية الاختبار الآلي لقواعد التصنيف المعاد بناؤها يزيد احتمال ظهور أخط', 'عدم كفاية تغطية الاختبار الآلي لقواعد التصنيف المعاد بناؤها يزيد احتمال ظهور أخطاء بعد الإطلاق.', 'جودة', 'متوسطة', 'متوسط', 'متوسط', 'عبدالرحمن الحربي', NULL, 'نشط', 'توسيع مجموعة الاختبارات الآلية لتغطية جميع سيناريوهات التصنيف الجديدة قبل الانتقال لاختبار القبول.', NULL, 'Manual'),
  (3013, 'PRJ-03', 'احتمال انسحاب أو تراجع دعم الرعاية التنفيذية للمشروع في حال استمرار التأخر دون م', 'احتمال انسحاب أو تراجع دعم الرعاية التنفيذية للمشروع في حال استمرار التأخر دون مؤشرات تعافٍ واضحة.', 'حوكمة', 'منخفضة', 'مرتفع', 'متوسط', 'نورة العتيبي', NULL, 'نشط', 'تقارير تعافٍ شهرية مفصلة للجنة التوجيهية توضح التقدم الفعلي مقابل خطة التعافي المعتمدة ومؤشرات الإنجاز.', NULL, 'Manual'),
  (5001, 'PRJ-05', 'احتمالية تعديل الخطة الاستراتيجية أثناء مرحلة البناء', 'احتمالية تعديل الخطة الاستراتيجية أثناء مرحلة البناء، مما يؤدي إلى عدم توافق نموذج المؤشرات المعتمد مع الأهداف والمبادرات المحدّثة.', NULL, 'متوسطة', 'مرتفع', 'عالٍ', 'مدير المشروع', NULL, 'نشط', 'التنسيق المستمر مع إدارة التخطيط الاستراتيجي لرصد أي مؤشرات مبكرة على تعديل الخطة، وتصميم نموذج المؤشرات بمرونة تسمح بإعادة الربط دون إعادة بناء كاملة.', NULL, 'Manual'),
  (5002, 'PRJ-05', 'عدم توفر مصادر بيانات موثوقة لعدد من المؤشرات التشغيلية لدى بعض الإدارات القطاعية', 'عدم توفر مصادر بيانات موثوقة لعدد من المؤشرات التشغيلية لدى بعض الإدارات القطاعية، مما يؤثر على دقة القياسات المدخلة في النظام.', NULL, 'مرتفعة', 'مرتفع', 'عالٍ', 'المالك التقني', NULL, 'نشط', 'إجراء جلسات تعيين مصادر البيانات (Data Source Mapping) مع كل جهة قطاعية، وتحديد بدائل مؤقتة للمؤشرات التي تفتقر لمصدر بيانات موثوق قبل الانتقال لمرحلة البناء.', NULL, 'Manual'),
  (5003, 'PRJ-05', 'ضعف مشاركة بعض الجهات القطاعية في اختبار وتبني سير عمل اعتماد القياسات', 'ضعف مشاركة بعض الجهات القطاعية في اختبار وتبني سير عمل اعتماد القياسات، مما قد يؤخر التشغيل التجريبي في البوابة الثانية.', NULL, 'متوسطة', 'متوسط', 'متوسط', 'ممثل الجهات القطاعية', NULL, 'نشط', 'إشراك ممثلي الجهات القطاعية مبكرًا في تصميم سير العمل، وتنظيم جلسات توعية وتدريب موجهة، ورفع أي تعثر ملحوظ إلى اللجنة التوجيهية.', NULL, 'Manual'),
  (5004, 'PRJ-05', 'توسع متطلبات لوحات الأداء المطلوبة من القيادة خارج النطاق المتفق عليه خلال دورات', 'توسع متطلبات لوحات الأداء المطلوبة من القيادة خارج النطاق المتفق عليه خلال دورات العرض التجريبي (Demo Cycles)، مما يؤثر على الجدول الزمني للبوابة الثالثة.', NULL, 'مرتفعة', 'متوسط', 'متوسط', 'مدير المشروع', NULL, 'نشط', 'اعتماد سجل رسمي لطلبات التغيير، وتقييم أي طلب إضافي من حيث الأثر على النطاق والجدول قبل الموافقة عليه، مع تخصيص احتياطي زمني محدود لهذا الغرض.', NULL, 'Manual'),
  (5005, 'PRJ-05', 'احتمالية تأخر تكامل النظام مع الأنظمة المصدرية القائمة', 'احتمالية تأخر تكامل النظام مع الأنظمة المصدرية القائمة (نظام تخطيط الموارد ونظام إدارة المبادرات) بسبب قيود تقنية غير متوقعة.', NULL, 'منخفضة', 'مرتفع', 'متوسط', 'المالك التقني', NULL, 'نشط', 'إجراء اختبار تكامل مبكر (Proof of Concept) لأهم نقاط التكامل خلال مرحلة التصميم التفصيلي، وتوثيق أي قيود فنية والتنسيق مع مالكي الأنظمة المصدرية مبكرًا.', NULL, 'Manual'),
  (5006, 'PRJ-05', 'دوران أو انشغال الموارد البشرية المخصصة للمشروع', 'دوران أو انشغال الموارد البشرية المخصصة للمشروع، وبالأخص فريق تحليل الأعمال، بمهام أخرى تؤثر على التزامهم بالجدول الزمني.', NULL, 'منخفضة', 'متوسط', 'منخفض', 'مدير المشروع', NULL, 'نشط', 'تثبيت تخصيص الموارد الرئيسية عبر خطابات رسمية من الإدارات المعنية، ومتابعة نسب الانشغال الفعلية أسبوعيًا من قبل مدير المشروع.', NULL, 'Manual'),
  (5007, 'PRJ-05', 'مقاومة التغيير لدى بعض منسوبي الجهات القطاعية تجاه اعتماد سير عمل إلكتروني موحد', 'مقاومة التغيير لدى بعض منسوبي الجهات القطاعية تجاه اعتماد سير عمل إلكتروني موحد بدلاً من الممارسات الحالية القائمة على جداول البيانات.', NULL, 'متوسطة', 'متوسط', 'متوسط', 'ممثل الجهات القطاعية', NULL, 'نشط', 'تنفيذ خطة إدارة تغيير مصاحبة تشمل التواصل المبكر والتدريب العملي وعرض الفوائد الملموسة لسير العمل الجديد قبل الإطلاق الكامل.', NULL, 'Manual'),
  (5008, 'PRJ-05', 'احتمالية عدم كفاية جودة البيانات التاريخية المستخدمة لتأسيس خطوط الأساس', 'احتمالية عدم كفاية جودة البيانات التاريخية المستخدمة لتأسيس خطوط الأساس (Baselines) لبعض المؤشرات الجديدة، مما يؤثر على مصداقية أول تقرير أداء فصلي.', NULL, 'متوسطة', 'منخفض', 'منخفض', 'محلل الأعمال', NULL, 'نشط', 'التحقق من جودة البيانات التاريخية مع الجهات المصدر قبل اعتماد خطوط الأساس، وتوثيق أي افتراضات أو تحفظات تصاحب المؤشرات التي تفتقر لبيانات تاريخية كافية.', NULL, 'Manual'),
  (6001, 'PRJ-06', 'عدم إكمال اختبار قبول المستخدم', 'عدم إكمال اختبار قبول المستخدم (UAT) قبل فتح نافذة دورة إعداد الميزانية القادمة في 30/09/2026.', 'جدول زمني', 'مرتفع', 'مرتفع جداً', 'عالٍ', 'مدير المشروع - سلطان الدوسري', NULL, 'مُصعّد إلى لجنة التوجيه', 'إعادة جدولة موارد الاختبار وتقديم خيار الإطلاق المخفض النطاق كخطة بديلة معتمدة.', NULL, 'Manual'),
  (6002, 'PRJ-06', 'عدم كفاية توفر كوادر وكالة الميزانية العامة للمشاركة في الاختبار بسبب تزامنه مع', 'عدم كفاية توفر كوادر وكالة الميزانية العامة للمشاركة في الاختبار بسبب تزامنه مع أعمال الإقفال السنوي.', 'موارد', 'متوسط', 'مرتفع', 'عالٍ', 'راعي المشروع - وكالة الميزانية العامة', NULL, 'مُصعّد إلى لجنة التوجيه', 'طلب تخصيص موارد اختبار إضافية مؤقتة من الوكالة بالتنسيق مع الإدارة التنفيذية.', NULL, 'Manual'),
  (6003, 'PRJ-06', 'اختلاف قواعد مسار الاعتماد المطبقة في النظام عن دليل التفويضات المالية', 'اختلاف قواعد مسار الاعتماد المطبقة في النظام عن دليل التفويضات المالية (DOA) المعتمد رسمياً.', 'امتثال', 'متوسط', 'مرتفع', 'عالٍ', 'مسؤول الامتثال - نورة القحطاني', NULL, 'قيد المتابعة على مستوى الفريق', 'مراجعة مشتركة مع الشؤون القانونية والمالية لمطابقة قواعد التوجيه مع الدليل قبل بدء الاختبار.', NULL, 'Manual'),
  (6004, 'PRJ-06', 'وجود عيوب برمجية غير محلولة في محرك الاعتماد متعدد المستويات تؤثر في مسارات التص', 'وجود عيوب برمجية غير محلولة في محرك الاعتماد متعدد المستويات تؤثر في مسارات التصعيد للمستوى الثالث.', 'تقني', 'مرتفع', 'مرتفع', 'عالٍ', 'مدير التطوير - فهد المطيري', NULL, 'قيد المتابعة على مستوى الفريق', 'تخصيص فريق إصلاح عيوب مخصص وإعطاء الأولوية للعيوب الحرجة والعالية قبل الدخول في الاختبار.', NULL, 'Manual'),
  (6005, 'PRJ-06', 'عدم اكتمال ترحيل بيانات المقارنة للسنة المالية السابقة لجميع الجهات الحكومية المشاركة.', 'عدم اكتمال ترحيل بيانات المقارنة للسنة المالية السابقة لجميع الجهات الحكومية المشاركة.', 'بيانات', 'متوسط', 'متوسط', 'متوسط', 'محلل البيانات - عبدالله الشمري', NULL, 'قيد المتابعة على مستوى الفريق', 'إغلاق التسويات المتبقية مع 4 جهات حكومية وتحديد موعد نهائي للترحيل قبل بدء الاختبار.', NULL, 'Manual'),
  (6006, 'PRJ-06', 'الخطر السمعي الناتج عن فشل الدورة الأولى للنظام واضطرار الجهات للعودة إلى العملية اليدوية.', 'الخطر السمعي الناتج عن فشل الدورة الأولى للنظام واضطرار الجهات للعودة إلى العملية اليدوية.', 'سمعة مؤسسية', 'متوسط', 'مرتفع جداً', 'عالٍ', 'راعي المشروع', NULL, 'مُصعّد إلى لجنة التوجيه', 'اعتماد خيار الإطلاق المخفض النطاق كخطة تراجع آمنة تضمن استمرارية دورة الإعداد دون انقطاع كامل.', NULL, 'Manual'),
  (6007, 'PRJ-06', 'تسرب النطاق نتيجة طلبات تعديل متكررة من الجهات الحكومية على نماذج التقديم أثناء', 'تسرب النطاق نتيجة طلبات تعديل متكررة من الجهات الحكومية على نماذج التقديم أثناء مرحلة البناء.', 'نطاق', 'منخفض', 'متوسط', 'منخفض', 'مدير المشروع', NULL, 'قيد المتابعة على مستوى الفريق', 'تجميد النطاق الأساسي رسمياً وإحالة أي طلبات إضافية إلى لجنة التغييرات لتقييمها بعد الإطلاق.', NULL, 'Manual'),
  (6008, 'PRJ-06', 'ضعف أداء لوحة مراقبة الانحرافات عند التعامل مع أحجام بيانات كبيرة من جميع الجهات', 'ضعف أداء لوحة مراقبة الانحرافات عند التعامل مع أحجام بيانات كبيرة من جميع الجهات في وقت واحد.', 'تقني', 'منخفض', 'متوسط', 'منخفض', 'مهندس النظم - ماجد العتيبي', NULL, 'قيد المتابعة على مستوى الفريق', 'إجراء اختبار حمل مبكر وتحسين استعلامات قاعدة البيانات قبل دخول مرحلة اختبار القبول.', NULL, 'Manual'),
  (6009, 'PRJ-06', 'تجاوز الميزانية المعتمدة نتيجة تسريع أعمال التطوير', 'تجاوز الميزانية المعتمدة نتيجة تسريع أعمال التطوير (موارد إضافية) لحماية موعد دورة الميزانية.', 'مالي', 'متوسط', 'متوسط', 'متوسط', 'مدير المشروع / الشؤون المالية', NULL, 'قيد المتابعة على مستوى الفريق', 'متابعة الصرف الفعلي مقابل المخطط شهرياً وتفعيل بند الطوارئ المعتمد ضمن الميزانية عند الحاجة.', NULL, 'Manual'),
  (6010, 'PRJ-06', 'احتمال تعارض جدول إجازات نهاية العام المالي مع الجدول الزمني الحرج لمرحلتي الاخت', 'احتمال تعارض جدول إجازات نهاية العام المالي مع الجدول الزمني الحرج لمرحلتي الاختبار والإطلاق.', 'جدول زمني', 'منخفض', 'متوسط', 'منخفض', 'مدير الموارد - هند البقمي', NULL, 'قيد المتابعة على مستوى الفريق', 'تثبيت خطة إجازات فريق العمل الأساسي مسبقاً وتحديد بدلاء لأصحاب الأدوار الحرجة.', NULL, 'Manual'),
  (7001, 'PRJ-07', 'Further regulatory findings identified after the current review, requiring addit', 'Further regulatory findings identified after the current review, requiring additional rework of the security architecture beyond the currently approved redesign.', 'Regulatory / Compliance', '3', '5', 'عالٍ', 'Faisal Al-Otaibi (Project Director)', NULL, 'نشط', 'Maintain a standing liaison channel with the regulatory review team; commission an independent compliance pre-check of the revised architecture before final Board submission.', NULL, 'Manual'),
  (7002, 'PRJ-07', 'Gateway throughput fails to meet peak load requirements during certification tes', 'Gateway throughput fails to meet peak load requirements during certification testing, requiring infrastructure or design changes.', 'Technical / Performance', '3', '4', 'متوسط', 'Turki Al-Ghamdi (Lead Platform Engineer)', NULL, 'نشط', 'Conduct incremental load testing ahead of formal certification; size infrastructure with 40% headroom above projected peak transaction volume.', NULL, 'Manual'),
  (7003, 'PRJ-07', 'Consuming systems are unable to adopt the new system-to-system authentication pa', 'Consuming systems are unable to adopt the new system-to-system authentication pattern within the transition window, delaying onboarding.', 'Operational / Adoption', '4', '3', 'متوسط', 'Nourah Al-Dossari (Integration Lead)', NULL, 'نشط', 'Provide reference implementations, sandbox credentials, and dedicated integration support to consuming system teams at least eight weeks before their onboarding slot.', NULL, 'Manual'),
  (7004, 'PRJ-07', 'Architecture expertise for the redesigned security layer is concentrated in a si', 'Architecture expertise for the redesigned security layer is concentrated in a single individual, creating a key-person dependency.', 'Resourcing', '3', '4', 'متوسط', 'Sara Al-Qahtani (Director General, DIC)', NULL, 'نشط', 'Formalise architecture decision records; cross-train a second senior engineer on the identity and token-handling design; engage the vendor for documented knowledge transfer sessions.', NULL, 'Manual'),
  (7005, 'PRJ-07', 'Prolonged coexistence of legacy point-to-point interfaces alongside the new gate', 'Prolonged coexistence of legacy point-to-point interfaces alongside the new gateway increases operational support cost and security exposure.', 'Operational / Cost', '4', '3', 'متوسط', 'Lama Al-Harbi (PMO)', NULL, 'نشط', 'Publish a phased decommissioning schedule tied to onboarding waves; report legacy interface count monthly to the Steering Committee.', NULL, 'Manual'),
  (7006, 'PRJ-07', 'The extended schedule pushes final cut-over into the Ministry''s year-end change', 'The extended schedule pushes final cut-over into the Ministry''s year-end change freeze period, delaying go-live to the following quarter.', 'Schedule', '4', '4', 'عالٍ', 'Faisal Al-Otaibi (Project Director)', NULL, 'نشط', 'Model cut-over scenarios against the published change freeze calendar; seek an approved exception window or plan cut-over for the first available slot after the freeze.', NULL, 'Manual'),
  (7007, 'PRJ-07', 'Extended vendor engagement required by the security redesign exceeds the contrac', 'Extended vendor engagement required by the security redesign exceeds the contracted professional services budget.', 'Financial', '3', '4', 'متوسط', 'Abdulrahman Al-Shehri (Finance Business Partner)', NULL, 'نشط', 'Track vendor day-rate consumption weekly against the revised estimate; submit the change request for additional funding early to avoid a stop-work situation.', NULL, 'Manual'),
  (7008, 'PRJ-07', 'Token lifetime and key rotation configuration approved by the Architecture Revie', 'Token lifetime and key rotation configuration approved by the Architecture Review Board is incompatible with a subset of legacy consuming systems'' authentication libraries.', 'Technical / Compatibility', '3', '3', 'متوسط', 'Turki Al-Ghamdi (Lead Platform Engineer)', NULL, 'نشط', 'Complete a compatibility survey of all Phase 1 consuming systems'' authentication stacks before finalising configuration; provide a compatibility library where feasible.', NULL, 'Manual'),
  (7009, 'PRJ-07', 'Delays in closing the two outstanding architecture amendments postpone the start', 'Delays in closing the two outstanding architecture amendments postpone the start of certification testing beyond the current forecast.', 'Schedule', '3', '4', 'متوسط', 'Nourah Al-Dossari (Integration Lead)', NULL, 'نشط', 'Assign a dedicated owner and weekly checkpoint for each amendment; escalate to the Architecture Review Board chair if either amendment slips beyond two weeks.', NULL, 'Manual'),
  (7010, 'PRJ-07', 'Stakeholder confidence in the revised completion date erodes further if slippage', 'Stakeholder confidence in the revised completion date erodes further if slippage recurs, affecting sponsorship and prioritisation of onboarding resources from consuming departments.', 'Reputational / Stakeholder', '3', '3', 'متوسط', 'Sara Al-Qahtani (Director General, DIC)', NULL, 'نشط', 'Maintain transparent weekly status reporting with quantified slippage; hold a joint briefing with major consuming departments once the revised baseline is confirmed by the Steering Committee.', NULL, 'Manual'),
  (7011, 'PRJ-07', 'API catalogue documentation lags behind actual service versions as onboarding re', 'API catalogue documentation lags behind actual service versions as onboarding resumes at pace, leading to integration errors by consuming teams.', 'Operational / Quality', '3', '2', 'منخفض', 'Turki Al-Ghamdi (Lead Platform Engineer)', NULL, 'نشط', 'Enforce documentation-as-a-release-gate in the onboarding checklist; automate catalogue publication from the service contract repository.', NULL, 'Manual'),
  (7012, 'PRJ-07', 'Cybersecurity Department capacity to review and re-approve subsequent architectu', 'Cybersecurity Department capacity to review and re-approve subsequent architecture amendments is constrained by competing regulatory reviews for other ministry projects.', 'Resourcing / Governance', '2', '4', 'متوسط', 'Faisal Al-Otaibi (Project Director)', NULL, 'نشط', 'Secure a standing review slot with the Cybersecurity Department for PRJ-07 amendments; escalate scheduling conflicts to the Steering Committee promptly.', NULL, 'Manual')
INSERT INTO issues (issue_id, project_code, issue_title, description, priority, owner, status, resolution, raised_date, resolved_date) VALUES
  (1001, 'PRJ-01', 'بطء في اعتماد وثائق التصميم', 'استغرقت دورة اعتماد وثيقة التصميم التفصيلي أطول من النافذة المخططة.', 'متوسطة', 'الأستاذ عبدالعزيز بن محمد الدوسري', 'مغلق', 'تم تقصير دورة الاعتماد باعتماد مراجعة متوازية.', '2025-11-24', '2025-12-18'),
  (1002, 'PRJ-01', 'فجوة في توثيق واجهات الربط', 'بعض واجهات الربط غير موثقة بالشكل الكافي لفريق التطوير.', 'منخفضة', 'الأستاذ عبدالعزيز بن محمد الدوسري', 'مفتوح', NULL, '2026-03-04', NULL),
  (2001, 'PRJ-02', 'تأخر استلام بيئة الاختبار من الجهة المشاركة', 'لم تُسلَّم بيئة اختبار التكامل في الموعد المتفق عليه، ما أخّر دورة اختبار القبول.', 'عالية', 'م. فيصل العتيبي', 'مفتوح', NULL, '2026-01-14', NULL),
  (2002, 'PRJ-02', 'نقص في موارد فريق ضمان الجودة', 'مغادرة مختبِرَين من الفريق أثناء مرحلة الاختبار دون إحلال فوري.', 'متوسطة', 'م. فيصل العتيبي', 'مغلق', 'تم التعاقد مع مورد لتوفير مختبِرَين بديلين خلال أسبوعين.', '2026-04-04', '2026-04-28'),
  (2003, 'PRJ-02', 'تعارض في جدولة ورش العمل مع الجهات المستفيدة', 'تعذّر عقد ورشتي مراجعة متطلبات بسبب ارتباطات الجهات المشاركة.', 'منخفضة', 'م. فيصل العتيبي', 'مفتوح', NULL, '2026-06-23', NULL),
  (3001, 'PRJ-03', 'تأخر اعتماد الميزانية التكميلية', 'لم تُعتمد الميزانية التكميلية اللازمة لاستكمال مرحلة التنفيذ.', 'عالية', 'غير محدد', 'مفتوح', NULL, '2025-05-25', NULL),
  (3002, 'PRJ-03', 'تغيّر في متطلبات الجهة المستفيدة بعد تجميد النطاق', 'طلبات تغيير متكررة بعد اعتماد خط الأساس أثّرت على الجدول الزمني.', 'عالية', 'غير محدد', 'مفتوح', NULL, '2025-09-02', NULL),
  (3003, 'PRJ-03', 'ضعف جاهزية البيانات المصدرية للترحيل', 'جودة البيانات في النظام القديم أقل من المستوى المطلوب للترحيل.', 'متوسطة', 'غير محدد', 'مغلق', 'تم تنفيذ حملة تنظيف بيانات استغرقت ثلاثة أسابيع.', '2025-12-11', '2026-01-04'),
  (4001, 'PRJ-04', 'ملاحظات على وثائق التسليم النهائي', 'طلبت الجهة المستفيدة استكمال أدلة التشغيل قبل التسليم النهائي.', 'متوسطة', 'م. فيصل بن سعد العتيبي', 'مغلق', 'استُكملت أدلة التشغيل واعتُمدت من الجهة المستفيدة.', '2024-10-13', '2024-11-06'),
  (4002, 'PRJ-04', 'تأخر نقل المعرفة لفريق التشغيل', 'تأخرت جلسات نقل المعرفة عن الموعد المخطط بأسبوعين.', 'منخفضة', 'م. فيصل بن سعد العتيبي', 'مغلق', 'عُقدت الجلسات واستُلمت شهادات الحضور.', '2025-01-16', '2025-02-09'),
  (5001, 'PRJ-05', 'بطء في اعتماد وثائق التصميم', 'استغرقت دورة اعتماد وثيقة التصميم التفصيلي أطول من النافذة المخططة.', 'متوسطة', 'م. نورة بنت فهد العتيبي', 'مغلق', 'تم تقصير دورة الاعتماد باعتماد مراجعة متوازية.', '2026-04-19', '2026-05-13'),
  (5002, 'PRJ-05', 'فجوة في توثيق واجهات الربط', 'بعض واجهات الربط غير موثقة بالشكل الكافي لفريق التطوير.', 'منخفضة', 'م. نورة بنت فهد العتيبي', 'مفتوح', NULL, '2026-07-14', NULL),
  (6001, 'PRJ-06', 'تأخر استلام بيئة الاختبار من الجهة المشاركة', 'لم تُسلَّم بيئة اختبار التكامل في الموعد المتفق عليه، ما أخّر دورة اختبار القبول.', 'عالية', 'م. سلطان بن عبدالعزيز الدوسري', 'مفتوح', NULL, '2025-09-21', NULL),
